BEGIN TRANSACTION;

UPDATE accounts SET balance = balance - 100 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 100 WHERE account_id = 2;

COMMIT TRANSACTION;

BEGIN TRANSACTION;

UPDATE accounts SET balance = balance - 100 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 100 WHERE account_id = 2;

ROLLBACK TRANSACTION;

BEGIN TRANSACTION;

INSERT INTO orders (customer_id, order_date, total_amount)
VALUES (42, GETDATE(), 59.98);

UPDATE products
SET stock_quantity = stock_quantity - 1
WHERE product_id = 7;

COMMIT TRANSACTION;

DECLARE @float_total FLOAT = 0;
DECLARE @decimal_total DECIMAL(10,2) = 0;

SET @float_total = @float_total + 0.1 + 0.2;
SET @decimal_total = @decimal_total + 0.1 + 0.2;

SELECT @float_total AS float_result, @decimal_total AS decimal_result;

CREATE TABLE customers (
    customer_id INT IDENTITY(1,1) PRIMARY KEY,
    customer_name VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL
);

-- Violates 1NF: 'products' column holds multiple values
CREATE TABLE orders_denormalized (
    order_id INT PRIMARY KEY,
    customer_name VARCHAR(100),
    products VARCHAR(500)  -- e.g. 'Widget, Gadget, Sprocket'
);

CREATE TABLE order_items (
    order_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL,
    PRIMARY KEY (order_id, product_id)
);

CREATE TABLE zip_codes (
    zip_code VARCHAR(10) PRIMARY KEY,
    city VARCHAR(100) NOT NULL,
    state VARCHAR(2) NOT NULL
);

CREATE TABLE customers (
    customer_id INT IDENTITY(1,1) PRIMARY KEY,
    customer_name VARCHAR(100) NOT NULL,
    zip_code VARCHAR(10) NOT NULL REFERENCES zip_codes (zip_code)
);

SELECT first_name, last_name, salary
FROM employees
WHERE salary > (SELECT AVG(salary) FROM employees);

SELECT customer_name
FROM customers
WHERE customer_id IN (SELECT customer_id FROM orders WHERE total_amount > 1000);

SELECT c.customer_name
FROM customers AS c
WHERE EXISTS (
    SELECT 1 FROM orders AS o WHERE o.customer_id = c.customer_id AND o.total_amount > 1000
);

SET STATISTICS IO ON;

SELECT first_name, last_name
FROM employees
WHERE department = 'Sales';

CREATE INDEX IX_employees_dept_salary ON employees (department, salary);

-- Can use the index efficiently (leading column):
SELECT * FROM employees WHERE department = 'Sales';

-- Can also use the index efficiently (both columns, in order):
SELECT * FROM employees WHERE department = 'Sales' AND salary > 50000;

SELECT first_name, last_name, department, salary,
       ROW_NUMBER() OVER (ORDER BY salary DESC) AS overall_rank
FROM employees;

SELECT first_name, last_name, department, salary,
       ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) AS dept_rank
FROM employees;

SELECT first_name, last_name, department, salary,
       AVG(salary) OVER (PARTITION BY department) AS department_average
FROM employees;

SELECT order_id, order_date, total_amount,
       SUM(total_amount) OVER (ORDER BY order_date) AS running_total
FROM orders;
